// two threads run this at the same time, balance starts at 100
if acct.Balance() >= 100 { // locks, reads, unlocks
	acct.Withdraw(100) // locks, subtracts, unlocks
}

// vectorises: iterations are independent
for (int i = 0; i < n; i++) c[i] = a[i] + b[i];

// does not: each step needs the previous result
for (int i = 1; i < n; i++) a[i] = a[i - 1] + b[i];
